JS=r"""()=>{
 const m=document.querySelector('main').cloneNode(true);
 m.querySelectorAll('script,style,dialog,[hidden],[aria-hidden=true],.erp-record-cover,#erp-late-message,nav[aria-label="Zum Material"],form.entry,footer').forEach(e=>e.remove());
